import json,re
from pathlib import Path
from collections import Counter
out=Path('/tmp/stationops-refinement')
def norm(s):
 names={}
 def variable(m):
  return names.setdefault(m[0], '$v'+str(len(names)))
 return re.sub(r'\$_\d+', variable, re.sub(r'kb[0-9a-f]{32}', 'kb',s))
def claims(name):
 d=json.loads((out/(name+'.json')).read_text()); start=d['batches'][1]['started_epoch'];end=start+d['batches'][1]['seconds']
 rows=[]
 for line in (out/(name+'.log')).read_text().splitlines():
  m=re.match(r'\(probe-claim (\S+) (\d+) (\S+) (\d+) (\d+) (\S+) (.*)\)$',line)
  if m and start <= float(m[1]) <= end:
   rows.append(dict(time=float(m[1])-start,remaining=int(m[2]),kind=m[3],gid=int(m[4]),depth=int(m[5]),score=float(m[6]),goal=norm(m[7])))
 return d,rows
if __name__=='__main__':
 for p in out.glob('*-600.json'):
  d,c=claims(p.stem); print(p.stem)
  print([(round(b['seconds'],3),b['inferences'],r['belief_metrics']) for b,r in zip(d['batches'],d['result']['rounds'])])
  print('depth counts',Counter(x['depth'] for x in c))
  (out/(p.stem+'-claims.json')).write_text(json.dumps(c,indent=2))
  for x in c:
   if '(Problem old coolant-pump' in x['goal'] or '(Problem old power-converter' in x['goal'] or '(PressureAlarm old coolant-pump shift-02' in x['goal']:
    print(x)
